"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type MarqueePrimitiveProps = ComponentProps<typeof motion.div>;

export function MarqueePrimitive({ children, ...props }: MarqueePrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {x: "0%"}}
      animate={{x: "-50%"}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 8, ease: [0.23, 1, 0.32, 1], repeat: Infinity, repeatType: "loop" }}
      aria-hidden="true"
    >
      {children}
    </motion.div>
  );
}
